-- Q889: SOC Reporting and Trust Services Criteria [easy/L2]
-- Issues: #1, #3
UPDATE questions SET
  choices = $EXPL$["Availability (system uptime assurance)","Processing Integrity (transaction accuracy)","Security (Common Criteria)","Privacy (personal data governance)"]$EXPL$::jsonb,
  explanation = $EXPL$Correct (C): Logical access controls restricting access to information assets based on roles fall under Security (Common Criteria) per AICPA TSP Section 100. Security controls protect against unauthorized access and form the foundation of the Trust Services framework.
Wrong (A): Availability addresses system uptime and operational resilience, not access restriction to information assets.
Wrong (B): Processing Integrity addresses completeness and accuracy of system processing, not access controls.
